    private function matchLabel(?EventEditionMatch $match): string
    {
        if (! $match) {
            return 'Sin partido asignado';
        }

        $round = $match->round_number ?? '?';
        $date = $match->match_date?->format('d/m/Y');
        $teams = trim(sprintf(
            '%s %s-%s %s',
