            ->get()
            ->mapWithKeys(fn (EventEditionTeamPlayer $player) => [
                (int) $player->person_id => $player->team?->name ?? '',
            ])
            ->all();
    }

    private function playerName($person): string
    {
        return $person?->full_name
            ?? trim((string) ($person?->names ?? ''))
            ?: 'Jugador sin nombre';
    }
