@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Montserrat:ital,wght@0,600;0,700;0,800;1,800;1,900&display=swap');

:root {
    --se-bg: #101d2d;
    --se-bg-elevated: #16283b;
    --se-bg-card: #0c1826;
    --se-accent: #b8f34a;
    --se-accent-glow: rgba(184, 243, 74, 0.28);
    --se-accent-2: #1b9447;
    --se-green: #35c46e;
    --se-red: #ef4444;
    --se-amber: #f59e0b;
    --se-text: #ffffff;
    --se-muted: #9ab0c4;
    --se-border: #26425c;
    --se-radius: 1rem;
    --se-radius-lg: 1.375rem;
    --se-header-h: 4.75rem;
    --se-font: 'Inter', system-ui, -apple-system, sans-serif;
    --se-display: 'Montserrat', 'Inter', system-ui, sans-serif;
    --se-max: 80rem;
}

*,
*::before,
*::after {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body.se-landing {
    margin: 0;
    font-family: var(--se-font);
    background: var(--se-bg);
    color: var(--se-text);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
}

body.se-landing ::selection {
    background: var(--se-accent);
    color: var(--se-bg);
}

.se-landing a {
    color: inherit;
    text-decoration: none;
}
