                'key' => $award->award_key,
                'label' => $award->label,
                'place' => $award->place,
            ])
            ->all();
    }

    private function initials(string $name): string
    {
        $initials = Str::of($name)
            ->squish()
            ->explode(' ')
            ->take(2)
            ->map(fn (string $part) => mb_strtoupper(mb_substr($part, 0, 1)))
            ->implode('');

        return $initials !== '' ? $initials : 'J';
